import unreal
rows=[]
for c in unreal.ObjectIterator(unreal.NiagaraComponent):
    try:
        a=c.get_asset()
        if a and a.get_path_name()=='/Game/SSPR_Validation/NS_SSPR_ProjTest.NS_SSPR_ProjTest':
            w=c.get_world()
            rows.append({'component':c.get_path_name(),'world':w.get_path_name() if w else None,'worldType':str(w.get_world_type()) if w and hasattr(w,'get_world_type') else None,'active':bool(c.is_active()),'tick':bool(c.is_component_tick_enabled()),'solo':bool(c.get_force_solo()),'ageMode':str(c.get_age_update_mode()),'owner':c.get_owner().get_path_name() if c.get_owner() else None})
    except Exception as e:
        rows.append({'component':c.get_path_name(),'error':str(e)})
print('PIE_RUNNING='+repr(unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_game_world() is not None))
print('MATCHING_COMPONENTS='+repr(rows))
